corpus_block("test-scales-breaks-labels.R: minor breaks draw correctly", {
  init_scale <- function(...) {
    sc <- scale_x_discrete(...)
    sc$train(factor(1:100))
    expect_length(sc$get_limits(), 100)
    sc
  }
  df <- data_frame(
      x_num = c(1, 3),
      x_chr = c("a", "b"),
      x_date = as.Date("2012-2-29") + c(0, 100),
      x_log = c(1, 1e4),
      y = c(1, 3)
    )
  theme <- theme_test() +
      theme(
        panel.grid.major = element_line(colour = "grey30", linewidth = 0.5),
        panel.grid.minor = element_line(colour = "grey70")
      )
  .plot("test-scales-breaks-labels.R: minor breaks draw correctly #1", p <- ggplot(df, aes(x_num, y)) +
      geom_blank() +
      scale_x_continuous(breaks = 1:3, minor_breaks = c(1.25, 2.75)) +
      scale_y_continuous(breaks = 1:3, minor_breaks = c(1.25, 2.75)) +
      labs(x = NULL, y = NULL) +
      theme)
  .plot("test-scales-breaks-labels.R: minor breaks draw correctly #2", p + coord_polar())
  .plot("test-scales-breaks-labels.R: minor breaks draw correctly #3", ggplot(df, aes(x_log, x_log)) + scale_x_continuous(transform = transform_log2()) + 
      scale_y_log10() + labs(x = NULL, y = NULL) + theme)
  .plot("test-scales-breaks-labels.R: minor breaks draw correctly #4", ggplot(df, aes(x_num, x_num)) + scale_x_continuous(transform = transform_exp(2)) + 
      scale_y_continuous(transform = transform_exp(2)) + labs(x = NULL, y = NULL) + 
      theme)
  .plot("test-scales-breaks-labels.R: minor breaks draw correctly #5", ggplot(df, aes(x_chr, y)) + geom_blank() + labs(x = NULL, y = NULL) + theme)
  .plot("test-scales-breaks-labels.R: minor breaks draw correctly #6", ggplot(df, aes(x_date, y)) + geom_blank() + scale_x_date(labels = scales::label_date("%m/%d"), 
      breaks = scales::date_breaks("month"), minor_breaks = scales::date_breaks("week")) + 
      labs(x = NULL, y = NULL) + theme)
})

