corpus_block("test-scales-breaks-labels.R: functional limits work for continuous scales", {
  init_scale <- function(...) {
    sc <- scale_x_discrete(...)
    sc$train(factor(1:100))
    expect_length(sc$get_limits(), 100)
    sc
  }
  limiter <- function(by) {
      function(limits) {
        low <- floor(limits[1] / by) * by
        high <- ceiling(limits[2] / by) * by
        c(low, high)
      }
    }
  .plot("test-scales-breaks-labels.R: functional limits work for continuous scales #1", ggplot(mpg, aes(class)) + geom_bar(aes(fill = drv)) + scale_y_continuous(limits = limiter(50)))
})

